    try:
        directory = load_strict(a.directory)
    except ValueError as e:
        print("REFUSED: %s" % e, file=sys.stderr)
        return 1

    result = verify(directory, key)

    if a.json:
        print(json.dumps(result, indent=2))
    else:
        for c in result["checks"]:
